import React from 'react';

// Compatibility wrapper for react-reveal Fade with React 19
// react-reveal is not compatible with React 19+, so we provide a simple fallback
export const Fade = ({ children, bottom, top, left, right, duration, distance, ...props }) => {
  return <>{children}</>;
};

export const Slide = ({ children, bottom, top, left, right, duration, distance, ...props }) => {
  return <>{children}</>;
};

export default Fade;
